    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G))
d=G['Demo pair 1 input']; do=G['Demo pair 1 output']
ti=G['Test input']
def solve(gi, flip):
    h,w=len(gi),len(gi[0])
    solid={i for i in range(h) if len(set(gi[i]))==1}
    br=min(solid)
    g = gi[::-1] if (br==0 or flip) else gi   # make divider the last row of working grid
    hh=len(g)
    bgv=Counter(x for r in g for x in r).most_common(1)[0][0]
    seen=set(); objs=[]
    for i in range(hh):
        if i==hh-1: continue
        for j in range(w):
            if g[i][j]!=bgv and (i,j) not in seen:
                c=g[i][j]; comp={(i,j)}; q=deque([(i,j)]); seen.add((i,j))
                while q:
                    a,b=q.popleft()
                    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                        na,nb=a+da,b+db
                        if 0<=na<hh and 0<=nb<w and (na,nb) not in seen and g[na][nb]==c:
                            comp.add((na,nb)); seen.add((na,nb)); q.append((na,nb))
                objs.append(comp)
    out=[[0]*w for _ in range(hh)]
    # divider: row gg[hh-1] originally at row br? In flipped case the divider lands at hh-1 naturally.
    # place divider row content first: use value from working grid's last row
    divval=g[hh-1][0]
    out[hh-1]=[divval]*w
    for c in sorted(objs,key=lambda c:-max(p[0] for p in c)):
        cells=sorted(c)
        best=None
        for dr in range(hh-2,-1,-1):
            if all(out[a+dr][b]==0 for a,b in cells):
                best=dr;break
        assert best is not None,(cells,)
        for a,b in cells:
            out[best+a][b]=g[a][b]
    if flip:
        out=out[::-1]          # flip back
    return out
# verify demo (no flip needed, divider at bottom)
print('demo ok:', solve(d,False)==do)
out=solve(ti,True)
for r in out: print(r)
print(json.dumps(out))

